comm -3 <(sort run_trace/expected_samples.txt) <(sort run_trace/final_samples.txt) || true
printf 'Expected samples: '; wc -l < run_trace/expected_samples.txt
printf 'Final samples: '; wc -l < run_trace/final_samples.txt
