  while (my $line=<$fh>) { chomp $line; my @f=split /'"\\t/,"'$line,-1; die "wrong fields at row $.'"\\n\" unless @f==@h; die \"bad seq at row "'$.'"\\n\" unless "'$f[0]=~/''^[ACGTN]+$/; die "duplicate seq at row $.'"\\n\" if "'$seen{$f[0]}++; for my $i (1..$#f) { die "bad count at row $. col $i: $f[$i]'"\\n\" unless "'$f[$i]=~/''^'"\\d+"'$/; } $rows++; }
  print "Validated ASV rows: $rows'"\\n\";
' final_answer/asv_abundance.tsv
printf 'Deliverables under final_answer:\\n'; find final_answer -maxdepth 1 -type f -printf '%P\\n' | sort"
